static SystemIndexMigrationInfo fromTaskState(
        SystemIndexMigrationTaskState taskState,
        SystemIndices systemIndices,
        Metadata metadata,
        IndexScopedSettings indexScopedSettings
    ) {
        SystemIndexDescriptor descriptor = systemIndices.findMatchingDescriptor(taskState.getCurrentIndex());
        SystemIndices.Feature feature = systemIndices.getFeature(taskState.getCurrentFeature());
        IndexMetadata imd = metadata.index(taskState.getCurrentIndex());

        // It's possible for one or both of these to happen if the executing node fails during execution and:
        // 1. The task gets assigned to a node with a different set of plugins installed.
        // 2. The index in question is somehow deleted before we got to it.
        // The first case shouldn't happen, master nodes must have all `SystemIndexPlugins` installed.
        // In the second case, we should just start over.
        if (descriptor == null) {
            String errorMsg = format(
                "couldn't find system index descriptor for index [%s] from feature [%s], which likely means this node is missing a plugin",
                taskState.getCurrentIndex(),
                taskState.getCurrentFeature()
            );
            logger.warn(errorMsg);
            assert false : errorMsg;
            throw new IllegalStateException(errorMsg);
        }

        if (imd == null) {
            String errorMsg = format(
                "couldn't find index [%s] from feature [%s] with descriptor pattern [%s]",
                taskState.getCurrentIndex(),
                taskState.getCurrentFeature(),
                descriptor.getIndexPattern()
            );
            logger.warn(errorMsg);
            assert false : errorMsg;
            throw new IllegalStateException(errorMsg);
        }

        return build(imd, descriptor, feature, indexScopedSettings);
    }

private void cancelExistingDataStreamMigrationAndMarkAsFailed(SystemDataStreamMigrationInfo migrationInfo, Exception exception) {
        logger.info(
            "cancelling migration of data stream [{}] from feature [{}]",
            migrationInfo.getDataStreamName(),
            migrationInfo.getFeatureName()
        );

        // we don't really care here if the request wasn't acknowledged
        ActionListener<AcknowledgedResponse> listener = ActionListener.wrap(response -> markAsFailed(exception), ex -> {
            exception.addSuppressed(ex);
            markAsFailed(exception);
        });

        cancelDataStreamMigration(migrationInfo, listener);
    }

private void cancelExistingDataStreamMigrationAndRetry(
        SystemDataStreamMigrationInfo migrationInfo,
        Consumer<SystemDataStreamMigrationInfo> completionListener
    ) {
        logger.debug(
            "cancelling migration of data stream [{}] from feature [{}] for retry",
            migrationInfo.getDataStreamName(),
            migrationInfo.getFeatureName()
        );

        ActionListener<AcknowledgedResponse> listener = ActionListener.wrap(response -> {
            if (response.isAcknowledged()) {
                migrateDataStream(migrationInfo, completionListener);
            } else {
                String dataStreamName = migrationInfo.getDataStreamName();
                logger.error(
                    "failed to cancel migration of data stream [{}] from feature [{}] during retry",
                    dataStreamName,
                    migrationInfo.getFeatureName()
                );
                throw new ElasticsearchException(
                    "failed to cancel migration of data stream ["
                        + dataStreamName
                        + "] from feature ["
                        + migrationInfo.getFeatureName()
                        + "] response is not acknowledge"
                );
            }
        }, this::markAsFailed);

        cancelDataStreamMigration(migrationInfo, listener);
    }

